from sys import exit


def eratosthenes(n):
    """
    n以下の整数の素数判定/列挙 (n > 1)
    O(NloglogN)
    """
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * 2, n + 1, i):
                is_prime[j] = False
    return [i for i in range(n + 1) if is_prime[i]]


def factorization(n):
    """
    素因数分解
    O(√N)
    """
    res = []
    m = 2
    while m**2 <= n:
        if n % m == 0:
            cnt = 0
            while n % m == 0:
                cnt += 1
                n //= m
            res.append([m, cnt])
        m += 1
    if n > 1:
        res.append([n, 1])
    return res


