    dist = abs(p0 - p1)
    if dist > 2:
        return []
    elif dist == 2:
        return [(p0 + p1) / 2]
    else:
        m = (p0 + p1) / 2
        v = m - p0
        w = complex(v.imag, -v.real)
        n = w / abs(w)
        d = abs(v)
        l = (1 - d**2) ** 0.5
        inter0 = m + l * n
        inter1 = m - l * n
        return [inter0, inter1]


