        それぞれの因数について最大であれば更新する
        """
        for i in range(len(arr)):
            num = arr[i]
            d = defaultdict(int)
            while num > 1:
                fact = self.prime[num]
                d[fact] += 1
                num //= fact
            for i in list(d.keys()):
                self.max_map[i] = max(self.max_map[i], d[i])
        ans = 1
        for i in list(self.max_map.keys()):
            ans = (ans * self.rep_sqr(i, self.max_map[i])) % self.p
        return ans


