import numpy as np


def Convolution(a, b):
    bit = (len(a) + len(b) - 2).bit_length()
    L = 2**bit
    fa, fb = np.fft.rfft(a, L), np.fft.rfft(b, L)
    c = np.rint(np.fft.irfft(fa * fb, L)).astype(np.int64)
    return c[: len(a) + len(b) - 1]


