def cmb(n, r):
    r = min(r, n - r)
    if r == 0:
        return 1
    if r == 1:
        return n
    f = 1
    for k in range(n, n - r, -1):
        f = (f * k) % MOD
        # n!/(n-r)!
    d = 1
    for k in range(2, r + 1):
        d = (d * k) % MOD
        # r!
    return (f * inv(d)) % MOD


