def next_arrival_time(current_time, info):
    if current_time <= info[1]:
        return info[1] + info[0]
    next_time = current_time
    remainder = next_time % info[2]
    while remainder != 0:
        next_time += 1
        remainder = next_time % info[2]
    while next_time < current_time:
        next_time += info[2]
    return next_time + info[0]


